import { expect, test, uniqueName } from "../../fixtures";

test.describe("REV-02 submit vendor with missing documents", () => {
  test(
    "submitting with only an extracted w9 returns 409 documents_incomplete listing missing kinds",
    { tag: "@REV-02" },
    async ({ apiAs }) => {
      // Arrange: signed-in member, draft vendor with a unique name and email
      const member = await apiAs("member");
      const suffix = Math.random().toString(36).slice(2, 10);

      const createResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("REV02 Vendor"),
          category: "services",
          contact_email: `rev02-${suffix}@example.test`,
        },
      });
      expect(createResponse.status()).toBe(201);
      const vendor = await createResponse.json();
      expect(vendor.status).toBe("draft");

      // Arrange: upload a w9 document
      const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "w9",
          file: {
            name: `w9-${suffix}.pdf`,
            mimeType: "application/pdf",
            buffer: Buffer.from(`%PDF-1.4 REV-02 w9 ${suffix}`),
          },
        },
      });
      expect(uploadResponse.status()).toBe(201);
      const document = await uploadResponse.json();

      // Arrange: wait until the document extraction finishes
      let status = document.status;
      const deadline = Date.now() + 60_000;
      while (status === "processing" && Date.now() < deadline) {
        await new Promise((resolve) => setTimeout(resolve, 1_000));
        const pollResponse = await member.get(`/api/documents/${document.id}`);
        expect(pollResponse.status()).toBe(200);
        status = (await pollResponse.json()).status;
      }
      expect(status).toBe("extracted");

      // Act: submit the vendor for review
      const submitResponse = await member.post(`/api/vendors/${vendor.id}/submit`);

      // Assert: 409 with documents_incomplete and the missing kinds named
      expect(submitResponse.status()).toBe(409);
      const body = await submitResponse.json();
      expect(body.error.code).toBe("documents_incomplete");
      const serialized = JSON.stringify(body);
      expect(serialized).toContain("contract");
      expect(serialized).toContain("insurance_certificate");
    },
  );
});
